function importUsers(filePath, db, mailer, done) {
  fs.readFile(filePath, 'utf8', function (err, text) {
    if (err) return done(err);
    var rows;
    try {
      rows = JSON.parse(text);
    } catch (e) {
      return done(new Error('bad json: ' + e.message));
    }
    var created = 0;
    var i = 0;
    function next() {
      if (i >= rows.length) return done(null, created);
      var row = rows[i++];
      db.findUserByEmail(row.email, function (err, existing) {
        if (err) return done(err);
        if (existing) return next();
        db.createUser(row, function (err, user) {
          if (err) return done(err);
          created++;
          mailer.sendWelcome(user.email, function (err) {
            if (err) console.warn('mail failed for ' + user.email);
            next();
          });
        });
      });
    }
    next();
  });
}
