async function getExchangeRate(from, to, { cache, now = Date.now } = {}) {
  const key = `${from}:${to}`;
  const hit = cache && cache.get(key);
  if (hit && now() - hit.at < 60_000) return hit.rate;

  const res = await axios.get('https://rates.example.com/latest', {
    params: { base: from, symbols: to },
    timeout: 3000,
  });
  const rate = res.data && res.data.rates && res.data.rates[to];
  if (typeof rate !== 'number') {
    throw new Error(`no rate for ${key}`);
  }
